source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                # This is the first cell of a maximal same-color diagonal run.
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for er, ec, sr, sc in ((run[0][0], run[0][1], -dr, -dc),
                                        (run[-1][0], run[-1][1], dr, dc)):
                    # Rays leave only exposed ends of a colored diagonal motif.
                    exposed = True
                    for nr in range(er - 1, er + 2):
                        for nc in range(ec - 1, ec + 2):
                            if (nr, nc) == (er, ec) or not (0 <= nr < h and 0 <= nc < w):
                                continue
                            if grid[nr][nc] not in (background, color):
                                exposed = False
                    if not exposed:
                        continue
                    nr, nc = er + sr, ec + sc
                    while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background:
                        out[nr][nc] = color
                        nr += sr
                        nc += sc
    return out
'''
